python3 -c "
import json
with open('/app/resources/treasury_bulletin_1992_03.json', 'r') as f:
    data = json.load(f)
# Search for TF-G or highway trust fund chart data
def search(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'TF-G' in str(k) or 'highway' in str(k).lower() or 'receipt' in str(k).lower():
                print(f'{path}.{k}: {str(v)[:200]}')
            search(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            search(item, f'{path}[{i}]')
search(data)
" 2>/dev/null | head -100

